  body+=f'<text x="{x}" y="{y+10}" text-anchor="middle" font-size="30">{s}</text>'
  used=[atan2(nodes[j if a==i else a][2]-y,nodes[j if a==i else a][1]-x) for a,j,o in edges if a==i or j==i];candidates=[-pi/2,pi/2,pi,0,-pi/4,pi/4,3*pi/4,-3*pi/4];chosen=[]
