 lines=t.split('\n');out=[];i=0
 while i<len(lines):
  if i+1<len(lines) and lines[i].startswith('|') and re.match(r'^\|[ :|\-]+\|$',lines[i+1]):
   cells=lambda line:[v.strip() for v in line.strip().strip('|').split('|')]
   out.append('<table><thead><tr>'+''.join('<th>'+v+'</th>' for v in cells(lines[i]))+'</tr></thead><tbody>');i+=2
   while i<len(lines) and lines[i].startswith('|'):
    out.append('<tr>'+''.join('<td>'+v+'</td>' for v in cells(lines[i]))+'</tr>');i+=1
   out.append('</tbody></table>');continue
  out.append(lines[i]+'<br>');i+=1
 return ''.join(out)
